COMMON = {}
for m in re.finditer(r'\*\*([a-z ]+):\*\* ([^.;:]*)', common_text):
    COMMON[m.group(1)] = ascii_text(m.group(2).strip())
# S's test track joins testFast, which the gate runs already, and the specification's build runs at the gather of
# each run, not in the gate: no rung brings a gate step (gateJoins names one such as testSpecData).
assert re.search(r"\*\*joins the gate:\*\* S's test track joins `testFast` \(section 4, S\); otherwise none, but the specification's build at each run's gather\.", common_text), ('common field', 'joins the gate', COMMON.get('joins the gate'))
want_common = {'writes state': 'no', 'its test is the stage': 'no', 'expected moves': 'none', 'lands only with': 'none',
               'expected checker count': 'none declared', 'expected checker crash': 'none'}
for k, v in want_common.items():
    assert COMMON.get(k) == v, ('common field', k, COMMON.get(k))

