    const total = sum.reduce((a, f) => a + +f[1], 0), cjt = sum.filter(f => f[0] === 'fast-compiler/CompilerJUTest').reduce((a, f) => a + +f[1], 0)
    const olj = sum.filter(f => f[0] === 'fast-onelibrary/OneLibraryJUTest').reduce((a, f) => a + +f[1], 0)
    const sys = sum.filter(f => /^system-[0-9]+\//.test(f[0])).reduce((a, f) => a + +f[1], 0)
    const atomic = fs.readFileSync(path.join(ROOT, last), 'utf8').split('\n').filter(l => /^# atomic .* PASS$/.test(l)).length
    say(sum.length === 64 && total === 3608 && cjt === 1766 && olj === 14 && sys === 878 && atomic === 72, 'the comparand\'s figures as the record gives them: ' + sum.length + ' suites, ' + total + ' tests, CompilerJUTest ' + cjt + ', OneLibraryJUTest ' + olj + ', the system shards ' + sys + ', ' + atomic + ' atomic runs PASS')
  }
